const test=require('node:test');
const assert=require('node:assert/strict');
const {readSigned24}=require('../adc.cjs');
test('sign extension',()=>{
  for(const [bytes,expected] of [[[0,0,0],0],[[255,255,127],8388607],[[0,0,128],-8388608],[[255,255,255],-1],[[0,255,255],-256]]) {
    assert.equal(readSigned24(Uint8Array.from(bytes)),expected);
  }
  const storage=Buffer.from([91,92,255,255,255,93]);
  assert.equal(readSigned24(storage.subarray(1,5),1),-1);
  assert.deepEqual([...storage],[91,92,255,255,255,93]);
});
test('bounds',()=>{
  for(const offset of [-1,1,0.5,NaN]) assert.throws(()=>readSigned24(Buffer.alloc(3),offset),RangeError);
  assert.throws(()=>readSigned24(Buffer.alloc(2)),RangeError);
});

