exports.readSigned24 = function(bytes, offset=0) {
  if(!Number.isInteger(offset) || offset<0 || offset+3>bytes.length) throw new RangeError('sample outside view');
  const unsigned=bytes[offset]+bytes[offset+1]*256+bytes[offset+2]*65536;
  return unsigned>=0x800000 ? unsigned-0x1000000 : unsigned;
};

